workflow DifferentArgument budget 1000000 {
  secret s: text max_tokens 8;
  secret flag: boolean max_tokens 1;
  input x: text max_tokens 100;
  input y: text max_tokens 100;
  model m = mock("offline-m") max_tokens 60;
  model n = mock("offline-n") max_tokens 400;
  prompt step(payload: text) -> text = "Process this payload: {payload}";
  if flag {
    let a: text = call step(x) using m;
  } else {
    let b: text = call step(y) using m;
  }
  output "done";
}

workflow ChainMatch budget 1000 {
  secret choose: boolean max_tokens 1;
  input source: text max_tokens 32;
  model shared = mock("research-model") max_tokens 4;
  prompt ask(t: text) -> text = "Request: {t}";
  if choose {
    let first_left: text = call ask(source) using shared;
    let second_left: text = call ask(first_left) using shared;
  } else {
    let first_right: text = call ask(source) using shared;
    let second_right: text = call ask(first_right) using shared;
  }
  output "complete";
}
